import{_ as i,o as a,c as o,ag as n}from"./chunks/framework.C9sp7nFj.js";const g=JSON.parse('{"title":"WaitCondition 条件等待","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/3. 等待指令/WaitCondition.md","filePath":"3. 指令/3. 等待指令/WaitCondition.md","lastUpdated":1778862643000}'),d={name:"3. 指令/3. 等待指令/WaitCondition.md"};function e(s,t,r,l,h,p){return a(),o("div",null,[...t[0]||(t[0]=[n(`<h1 id="waitcondition-条件等待" tabindex="-1">WaitCondition 条件等待 <a class="header-anchor" href="#waitcondition-条件等待" aria-label="Permalink to &quot;WaitCondition 条件等待&quot;">​</a></h1><p>该指令用于根据逻辑表达式的结果进行程序阻塞等待。它是最灵活的等待指令，不仅限于 IO 信号，还可以对变量值、数学运算结果或多个条件的组合进行综合判定。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><h2 id="waitcondition-c-t-ie-tv-goto-waitcondition-判别条件-时长-中断使能-超时判断值-跳转标签-备注-带-参数为可选参数" tabindex="-1">WaitCondition(C, T, IE, TV, [Goto]) WaitCondition(判别条件, 时长, 中断使能, 超时判断值, [跳转标签]) <em>(备注：带 [] 参数为可选参数)</em> <a class="header-anchor" href="#waitcondition-c-t-ie-tv-goto-waitcondition-判别条件-时长-中断使能-超时判断值-跳转标签-备注-带-参数为可选参数" aria-label="Permalink to &quot;WaitCondition(C, T, IE, TV, [Goto])
WaitCondition(判别条件, 时长, 中断使能, 超时判断值, [跳转标签])
*(备注：带 [] 参数为可选参数)*&quot;">​</a></h2><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>C（判别条件）</td><td>string 表达式</td><td>逻辑表达式（如 <code>&quot;R1 &gt; 10&quot;</code> 或 <code>&quot;B1 == TRUE &amp;&amp; DI1 == ON&quot;</code>），结果为真时程序才向下运行</td><td>无</td></tr><tr><td>T（时长）</td><td>int / INT</td><td>等待时间，单位 ms（毫秒）。0 表示永久等待直到条件成立；&gt;0 表示最长等待毫秒数</td><td>0</td></tr><tr><td>IE（中断使能）</td><td>0 或 1</td><td>定义程序暂停后的计时策略。0：恢复后从暂停时刻继续累加；1：恢复后重新从 0 开始计时</td><td>无</td></tr><tr><td>TV（超时判断值）</td><td>INT 变量（如 V 变量）</td><td>反馈指令完成状态。0：条件满足成功通过；1：等待超时</td><td>无</td></tr><tr><td>[Goto]（跳转标签）</td><td>Label</td><td>可选参数。若超时，程序不执行下一行，直接跳转到指定标签位置</td><td>无</td></tr></tbody></table><hr><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：复杂逻辑判定</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">WaitCondition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;R10 &gt;= 50.5 &amp;&amp; DI5 == ON&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, V1, Error_Handle)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>逻辑解析：</strong></p><ol><li>监控内容：同时检查变量 <strong>R10</strong> 是否大于等于 50.5，且 <strong>DI5</strong> 端口是否为接通状态。</li><li>时限：给系统 <strong>2 秒</strong>（2000ms）时间去达成上述条件。</li><li>成功：若达成，<strong>V1 = 0</strong>，程序执行下一行。</li><li>超时：若 2 秒后条件仍不满足，<strong>V1 = 1</strong>，程序直接跳转到标签 <code>Error_Handle</code> 处执行异常处理。</li></ol><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>该指令将程序暂停执行，持续监控指定的逻辑表达式。当表达式结果为真时，程序继续向下执行；若在指定时间内条件始终不满足，则根据参数配置进行超时处理。</p>`,14)])])}const k=i(d,[["render",e]]);export{g as __pageData,k as default};
